  }
  if (p.cores <= 20u && p.e > 1u && p.e <= 16u && p.m / p.e >= 64u &&
      p.m / p.e < 256u && p.n >= 384u && p.n <= 640u && p.n % 128u == 0u &&
      p.k >= 128u && p.k <= 512u && p.k % 128u == 0u) {
    Plan selected = p;
    if (ConfigureCubeFullK<64, 128, 128, 64, true, false>(selected)) {
      if (bf && p.k == 256u && p.n == 512u && p.e == 8u && p.cores == 20u)
        panel_tiles::Launch<128, 256, 64, 16>(x, weight, xScale, weightScale, groupList,
                                              y, selected, stream);
      else
        LaunchAlignedTiles(x, weight, xScale, weightScale, groupList, y, selected, bf,
                           stream);
      return;
    }
  }
  const bool packWeights = p.m / p.e >= 256u && p.n >= 512u && p.n % 32u != 0u &&
                           p.k >= 128u &&
                           uint64_t(p.m / p.e >= 512u ? 464u : 480u) * p.kp <= L1_BYTES;
  if (packWeights && p.cores == 20u) {
    if (bf && p.k == 1023u && p.n == 1025u && p.e == 7u && p.m / p.e < 512u) {
      packed_tail::Launch<true, 1023, 1025, 7>(x, weight, xScale, weightScale,
                                               groupList, y, p, stream);
      return;
    }
    if (!bf && p.k == 767u && p.n == 1025u && p.e == 4u) {
      packed_tail::Launch<false, 767, 1025, 4>(x, weight, xScale, weightScale,
                                               groupList, y, p, stream);
      return;
    }
  }
  if (packWeights) {
    Plan packed = p;
    packed.wstride = UpH(p.n, 128u);
    if (bf && p.cores <= 20u && p.e <= 16u && p.m / p.e < 512u && p.k > 512u &&
        p.k <= 1024u && p.n <= 1280u && uint64_t(480u) * p.kp <= 524032u &&
        ConfigureCubeFullK<192, 128, 128, 64, true, false>(packed)) {
      Scratch packedWeight(uint64_t(p.e) * p.k * packed.wstride);
      LaunchPackedWeights<true>(x, weight, xScale, weightScale, groupList, y,
                                (GM_ADDR)packedWeight.p, packed, stream);
      return;
    }
    if (!bf && ConfigureCubeFullK<224, 128, 128, 64, true, false>(packed) &&
        p.e <= 16u && p.cores <= 20u && p.k <= 1024u && p.n <= 1280u &&
        uint64_t(480u) * p.kp <= 524032u) {
      Scratch packedWeight(uint64_t(p.e) * p.k * packed.wstride);
      LaunchPackedWeights<false>(x, weight, xScale, weightScale, groupList, y,
                                 (GM_ADDR)packedWeight.p, packed, stream);
      return;
    }
  }
  const uint32_t rowsPerExpert = p.m / p.e;
  if (bf && p.cores <= 20u && p.e > 1u && p.e <= 16u && p.m / p.e >= 96u &&
      p.m / p.e < 256u && p.n >= 192u && p.n <= 320u && p.k > 256u && p.k <= 384u) {
    Plan selected = p;
    if (ConfigureCubeFullK<96, 128, 384, 48, false, true>(selected)) {
      LaunchNarrowN(x, weight, xScale, weightScale, groupList, y, selected, stream);
      return;
    }
  }
  if (rowsPerExpert < 96 && p.n <= 640 && p.kp <= 512 &&
      ConfigureCubeFullK<96, 128, 512, 48, false, true>(p)) {
    if (bf && p.k == 511u && p.n == 513u && p.e == 4u && p.cores == 20u)
      LaunchShortRows<true>(x, weight, xScale, weightScale, groupList, y, p, bf,
                            stream);
    else
      LaunchShortRows<false>(x, weight, xScale, weightScale, groupList, y, p, bf,
                             stream);
    return;
  }
  if (!bf && availableCoreNum <= 20 && rowsPerExpert >= 256u && p.n >= 512u &&
      p.n % 256u == 0u && p.k % 128u == 0u && p.wstride == p.n &&
      uint64_t(128u + 2u * 256u) * p.kp <= 524032u) {
    Plan selected = p;
    selected.cores = std::min(selected.cores, 20u);
    if (ConfigureCubeFullK<128, 256, 128, 32, true, false>(selected)) {
      half_pair::Launch(x, weight, xScale, weightScale, groupList, y, selected, stream);
      return;
    }
  }
  p.wstride = p.n;
  LeanPlanCube(p);
  Scratch scratch(CubeFullKStagingBytes(p));
  LaunchAndSync(stream, [&] {
    GMM_BY_DTYPE(CubeMix, p.cores, x, weight, xScale, weightScale, groupList, y,
                 (GM_ADDR)scratch.p, p);
  });
}
#undef GMM_BY_DTYPE
#undef GMM_BY_DTYPE_1T
#undef GMM_BY_DTYPE_2T
#undef GMM_BY_BF
#undef GMM_BY_BF_CALL
extern "C" void run_kernel(GM_ADDR x, const TensorGroupInfo& info_x, GM_ADDR weight,
                           const TensorGroupInfo& info_weight, GM_ADDR xScale,
                           const TensorGroupInfo& info_xScale, GM_ADDR weightScale,
                           const TensorGroupInfo& info_weightScale, GM_ADDR groupList,
                           const TensorGroupInfo& info_groupList, GM_ADDR y,
                           const TensorGroupInfo& info_y, int64_t availableCoreNum,
                           aclrtStream stream, int64_t groupListType,
                           const char* outputDtype) {
  GmmRunKernelBody(x, info_x, weight, info_weight, xScale, info_xScale, weightScale,
                   info_weightScale, groupList, info_groupList, y, info_y,
                   availableCoreNum, stream, groupListType, outputDtype);
  const int probePoint = GmmProbePoint(info_x, info_weight, groupListType);
  if (probePoint >= 0 && kGmmProbeTicks[probePoint]) {
    GmmProbeSpin<<<1, nullptr, stream>>>(kGmmProbeTicks[probePoint]);
    gmmptq::Check(aclrtSynchronizeStream(stream));
  }
}

#include <array>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <cmath>
#include "acl/acl.h"
#ifndef GM_ADDR
#define GM_ADDR __gm__ uint8_t*
#endif
#ifndef TENSOR_GROUP_INFO_DEFINED
#define TENSOR_GROUP_INFO_DEFINED
struct TensorInfo {
    const int64_t* shape;
    int64_t numDims;
    int32_t dtype;
};
struct TensorGroupInfo {
    const TensorInfo* tensors;
    int64_t numTensors;
};
#endif
#ifdef ASCENDC_CPU_DEBUG
#include "cpu_debug_launch.h"
#endif
#include "kernel.asc"

static void check(aclError code) {
    if (code != ACL_SUCCESS)
        throw std::runtime_error("ACL call failed: " + std::to_string(code));
}
struct DeviceMemory {
    std::vector<void*> pointers;
    void* allocate(size_t bytes) {
        void* ptr = nullptr;
        check(aclrtMalloc(&ptr, bytes ? bytes : 1, ACL_MEM_MALLOC_HUGE_FIRST));
        pointers.push_back(ptr);
        return ptr;
    }
    ~DeviceMemory() {
        for (auto ptr : pointers)
            aclrtFree(ptr);
    }
};
struct Session {
    int device;
    aclrtStream stream = nullptr;
    bool initialized = false, selected = false;
    explicit Session(int number) : device(number) {
    }
    void start() {
        check(aclInit(nullptr));
        initialized = true;
        check(aclrtSetDevice(device));
        selected = true;
        check(aclrtCreateStream(&stream));
    }
    ~Session() {
        if (stream)
            aclrtDestroyStream(stream);
        if (selected)
            aclrtResetDevice(device);
        if (initialized)
            aclFinalize();
    }
};
struct Tensor {
    std::vector<int64_t> shape;
    int32_t dtype;
    size_t bytes;
    std::string file;
};
struct Group {
    std::vector<Tensor> tensors;
    std::vector<void*> data;
    std::vector<TensorInfo> infos;
    DeviceMemory memory;
    void* pointer = nullptr;
    TensorGroupInfo info{nullptr, 0};
    Group(std::vector<Tensor> specs, bool dynamic, bool input) : tensors(std::move(specs)) {
        for (auto& spec : tensors) {
            void* ptr = memory.allocate(spec.bytes);
            data.push_back(ptr);
            infos.push_back(
                {spec.shape.data(), static_cast<int64_t>(spec.shape.size()), spec.dtype});
            if (input) {
                std::ifstream file("input/" + spec.file, std::ios::binary | std::ios::ate);
                if (!file || file.tellg() != static_cast<std::streamoff>(spec.bytes))
                    throw std::runtime_error("input size mismatch: " + spec.file);
                std::vector<char> host(spec.bytes);
                file.seekg(0);
                if (spec.bytes && !file.read(host.data(), spec.bytes))
                    throw std::runtime_error("input read failed: " + spec.file);
                if (spec.bytes)
                    check(aclrtMemcpy(ptr, spec.bytes, host.data(), spec.bytes,
                                      ACL_MEMCPY_HOST_TO_DEVICE));
            } else if (spec.bytes) {
                check(aclrtMemset(ptr, spec.bytes, 0xA5, spec.bytes));
            }
        }
        info = {infos.data(), static_cast<int64_t>(infos.size())};
        if (data.empty())
            return;
        if (dynamic) {
            std::vector<uint64_t> addresses;
            for (auto ptr : data)
                addresses.push_back(reinterpret_cast<uint64_t>(ptr));
            size_t bytes = addresses.size() * sizeof(uint64_t);
            pointer = memory.allocate(bytes);
            check(aclrtMemcpy(pointer, bytes, addresses.data(), bytes, ACL_MEMCPY_HOST_TO_DEVICE));
        } else
            pointer = data[0];
    }
    void save() {
        for (size_t i = 0; i < tensors.size(); ++i) {
            auto& spec = tensors[i];
            std::vector<char> host(spec.bytes);
            if (spec.bytes)
                check(aclrtMemcpy(host.data(), spec.bytes, data[i], spec.bytes,
                                  ACL_MEMCPY_DEVICE_TO_HOST));
            std::ofstream file("output/" + spec.file, std::ios::binary | std::ios::trunc);
            if (!file || (spec.bytes && !file.write(host.data(), spec.bytes)))
                throw std::runtime_error("output write failed: " + spec.file);
        }
    }
};

int main(int argc, char** argv) {
    try {
        if (argc > 2)
            throw std::runtime_error("usage: ./sample [device_id]");
        std::string value = argc == 2 ? argv[1] : "0";
        size_t used = 0;
        int device = std::stoi(value, &used);
        if (used != value.size() || device < 0 || device > 1023)
            throw std::runtime_error("invalid device ID");
        Session session(device);
        session.start();
#ifdef ASCENDC_CPU_DEBUG
        int64_t cores = 1;
#else
        int64_t cores = 0;
        check(aclrtGetDeviceInfo(device, ACL_DEV_ATTR_AICORE_CORE_NUM, &cores));
#endif
        if (cores <= 0)
            throw std::runtime_error("device has no matching cores");
        Group group_0({Tensor{{4096, 768}, 3, 3145728, "x.bin"}}, false, true);
        Group group_1({Tensor{{4, 768, 1024}, 3, 3145728, "weight.bin"}}, false, true);
        Group group_2({Tensor{{4096}, 0, 16384, "xScale.bin"}}, false, true);
        Group group_3({Tensor{{4, 1024}, 0, 16384, "weightScale.bin"}}, false, true);
        Group group_4({Tensor{{4}, 6, 32, "groupList.bin"}}, false, true);
        Group group_5({Tensor{{4096, 1024}, 1, 8388608, "y.bin"}}, false, false);
        int64_t attr_0 = 0LL;
        const char* attr_1 = "float16";
        run_kernel(
            (GM_ADDR)group_0.pointer,
            group_0.info,
            (GM_ADDR)group_1.pointer,
            group_1.info,
            (GM_ADDR)group_2.pointer,
            group_2.info,
            (GM_ADDR)group_3.pointer,
            group_3.info,
            (GM_ADDR)group_4.pointer,
            group_4.info,
            (GM_ADDR)group_5.pointer,
            group_5.info,
            cores,
            session.stream,
            attr_0,
            attr_1);
        check(aclrtSynchronizeStream(session.stream));
        group_5.save();
        std::cout << "Sample kernel completed; outputs saved for verification.\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << "RUN ERROR: " << error.what() << '\n';
        return 2;
    }
}
